CREATE DATABASE IF NOT EXISTS northwind;
USE northwind;

-- Tablas
DROP TABLE IF EXISTS OrderDetails, Orders, Products, Categories, Customers, Employees, Shippers, Suppliers;
CREATE TABLE Categories (CategoryID INT PRIMARY KEY, CategoryName VARCHAR(100));
CREATE TABLE Products (ProductID INT PRIMARY KEY, ProductName VARCHAR(100), CategoryID INT, UnitPrice DECIMAL(10,2));
CREATE TABLE Customers (CustomerID INT PRIMARY KEY, CompanyName VARCHAR(100), City VARCHAR(100), Country VARCHAR(100));
CREATE TABLE Employees (EmployeeID INT PRIMARY KEY, FirstName VARCHAR(100), LastName VARCHAR(100));
CREATE TABLE Shippers (ShipperID INT PRIMARY KEY, CompanyName VARCHAR(100));
CREATE TABLE Suppliers (SupplierID INT PRIMARY KEY, CompanyName VARCHAR(100));
CREATE TABLE Orders (OrderID INT PRIMARY KEY, CustomerID INT, EmployeeID INT, ShipperID INT, OrderDate DATE);
CREATE TABLE OrderDetails (OrderID INT, ProductID INT, Quantity INT, UnitPrice DECIMAL(10,2));

